package com.gangchil.counter;
import android.Manifest;import android.app.*;import android.os.*;import android.content.*;import android.content.pm.PackageManager;import android.bluetooth.*;import android.hardware.usb.*;import android.webkit.*;import org.json.*;import java.util.*;import java.io.*;
public class MainActivity extends Activity {
 static final String SITE="https://gangchil.42web.io";WebView web,printView;ValueCallback<android.net.Uri[]> upload;android.content.SharedPreferences prefs;
 public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("counter",0);if(!prefs.contains("deviceKey"))prefs.edit().putString("deviceKey",UUID.randomUUID().toString()).commit();
 web=new WebView(this);printView=web;setContentView(web);web.getSettings().setSupportMultipleWindows(true);web.getSettings().setJavaScriptCanOpenWindowsAutomatically(true);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setDomStorageEnabled(true);web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(false);web.getSettings().setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);CookieManager.getInstance().setAcceptCookie(true);prefs.edit().putString("ua",web.getSettings().getUserAgentString()).apply();web.addJavascriptInterface(new Bridge(),"GangchilAndroid");
 web.setWebViewClient(new WebViewClient(){public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return !SITE.equals(origin(r.getUrl().toString()));}public void onPageFinished(WebView v,String url){CookieManager.getInstance().flush();prefs.edit().putString("cookie",CookieManager.getInstance().getCookie(SITE)==null?"":CookieManager.getInstance().getCookie(SITE)).apply();v.evaluateJavascript("window.GangchilNative={info:()=>Promise.resolve(JSON.parse(GangchilAndroid.info())),configure:s=>Promise.resolve(JSON.parse(GangchilAndroid.configure(JSON.stringify(s)))).then(r=>{if(r.error)throw Error(r.error);return r}),test:()=>Promise.resolve(JSON.parse(GangchilAndroid.test())).then(r=>{if(r.error)throw Error(r.error);return r})};window.print=()=>GangchilAndroid.printPage();document.addEventListener('click',async e=>{const a=e.target.closest('a');if(a&&a.href.startsWith('blob:')){e.preventDefault();const b=await fetch(a.href).then(r=>r.blob());const r=new FileReader();r.onload=()=>GangchilAndroid.saveFile(r.result.split(',')[1],b.type);r.readAsDataURL(b)}},true)",ignored->{try{ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=getAssets().open("native-ui.js")){byte[] buf=new byte[4096];int n;while((n=in.read(buf))>0)out.write(buf,0,n);}v.evaluateJavascript(out.toString("UTF-8"),null);}catch(Exception e){}});}});
 web.setWebChromeClient(new WebChromeClient(){@Override public boolean onCreateWindow(WebView view,boolean dialogMode,boolean gesture,Message message){if(!gesture)return false;Dialog dialog=new Dialog(MainActivity.this);WebView child=new WebView(MainActivity.this);child.getSettings().setJavaScriptEnabled(true);child.getSettings().setDomStorageEnabled(true);child.getSettings().setAllowFileAccess(false);child.addJavascriptInterface(new Bridge(),"GangchilAndroid");child.setWebViewClient(web.getWebViewClient());child.setWebChromeClient(this);dialog.setContentView(child);dialog.setOnDismissListener(d->{printView=web;child.destroy();});dialog.show();dialog.getWindow().setLayout(-1,-1);printView=child;WebView.WebViewTransport transport=(WebView.WebViewTransport)message.obj;transport.setWebView(child);message.sendToTarget();return true;}@Override public boolean onShowFileChooser(WebView v,ValueCallback<android.net.Uri[]> cb,FileChooserParams params){if(upload!=null)upload.onReceiveValue(null);upload=cb;try{startActivityForResult(params.createIntent(),11);return true;}catch(Exception e){upload=null;return false;}}});
 web.setDownloadListener((url,ua,disposition,mime,size)->{if(url.startsWith("blob:")){web.evaluateJavascript("fetch("+JSONObject.quote(url)+").then(r=>r.blob()).then(b=>{const r=new FileReader();r.onload=()=>GangchilAndroid.saveFile(r.result.split(',')[1],b.type);r.readAsDataURL(b)})",null);}else if(SITE.equals(origin(url))){android.app.DownloadManager.Request request=new android.app.DownloadManager.Request(android.net.Uri.parse(url));request.addRequestHeader("Cookie",CookieManager.getInstance().getCookie(SITE));request.addRequestHeader("User-Agent",ua);request.setNotificationVisibility(1);request.setDestinationInExternalFilesDir(this,android.os.Environment.DIRECTORY_DOWNLOADS,URLUtil.guessFileName(url,disposition,mime));getSystemService(android.app.DownloadManager.class).enqueue(request);android.widget.Toast.makeText(this,"Downloading report",0).show();}});
 web.loadUrl(SITE+"/staff/");if(Build.VERSION.SDK_INT>=31&&checkSelfPermission(Manifest.permission.BLUETOOTH_CONNECT)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.BLUETOOTH_CONNECT},1);
 }
 String origin(String value){try{android.net.Uri u=android.net.Uri.parse(value);return u.getScheme()+"://"+u.getAuthority();}catch(Exception e){return "";}}
 boolean trusted(){return web.getUrl()!=null&&SITE.equals(origin(web.getUrl()));}
 class Bridge {
 @JavascriptInterface public String info(){try{JSONObject out=new JSONObject();JSONArray printers=new JSONArray();BluetoothManager bm=getSystemService(BluetoothManager.class);BluetoothAdapter bt=bm==null?null:bm.getAdapter();if(bt!=null)try{for(BluetoothDevice d:bt.getBondedDevices())printers.put(new JSONObject().put("name","Bluetooth · "+(d.getName()==null?"Printer":d.getName())+" · "+d.getAddress()));}catch(SecurityException ignored){}
 UsbManager um=getSystemService(UsbManager.class);for(UsbDevice d:um.getDeviceList().values())printers.put(new JSONObject().put("name","USB · "+(d.getProductName()==null?"Printer":d.getProductName())+" · "+d.getDeviceName()));
 return out.put("printers",printers).put("selected",prefs.getString("printer","")).put("deviceKey",prefs.getString("deviceKey","")).put("paired",prefs.contains("token")).put("status",prefs.getString("status","Select a connected printer")).toString();}catch(Exception e){return "{}";}}
 @JavascriptInterface public String configure(String raw){try{JSONObject s=new JSONObject(raw);String name=s.getString("name"),token=s.getString("token");if(!token.matches("[a-f0-9]{64}"))throw new Exception("Sign in to configure printing");JSONArray choices=new JSONObject(info()).getJSONArray("printers");boolean found=false;for(int i=0;i<choices.length();i++)if(choices.getJSONObject(i).getString("name").equals(name))found=true;if(!found)throw new Exception("Printer not connected");String mode=name.startsWith("USB")?"usb":"bt",device=name.substring(name.lastIndexOf(" · ")+3);
 if(mode.equals("usb")){UsbManager um=getSystemService(UsbManager.class);UsbDevice d=um.getDeviceList().get(device);if(d==null)throw new Exception("USB disconnected");if(!um.hasPermission(d)){um.requestPermission(d,PendingIntent.getBroadcast(MainActivity.this,0,new Intent(getPackageName()+".USB_PERMISSION").setPackage(getPackageName()),PendingIntent.FLAG_IMMUTABLE));throw new Exception("Allow USB access, then select the printer again");}}
 prefs.edit().putString("printer",name).putString("mode",mode).putString("device",device).putString("token",token).putString("status","Ready · "+name).commit();runOnUiThread(()->{if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},2);startForegroundService(new Intent(MainActivity.this,QueueService.class));});return "{\"ok\":true}";
 }catch(Exception e){return error(e);}}
 @JavascriptInterface public void printPage(){runOnUiThread(()->{android.print.PrintManager manager=getSystemService(android.print.PrintManager.class);manager.print("Gangchil report",printView.createPrintDocumentAdapter("Gangchil report"),null);});}
 @JavascriptInterface public void saveFile(String base64,String mime){try{if(base64.length()>28000000)throw new Exception("Report too large");String ext=mime.equals("application/pdf")?"pdf":mime.equals("image/png")?"png":"html";byte[] bytes=android.util.Base64.decode(base64,0);String name="gangchil-report-"+System.currentTimeMillis()+"."+ext;if(Build.VERSION.SDK_INT>=29){ContentValues values=new ContentValues();values.put(android.provider.MediaStore.Downloads.DISPLAY_NAME,name);values.put(android.provider.MediaStore.Downloads.MIME_TYPE,mime);values.put(android.provider.MediaStore.Downloads.IS_PENDING,1);android.net.Uri uri=getContentResolver().insert(android.provider.MediaStore.Downloads.EXTERNAL_CONTENT_URI,values);try(OutputStream out=getContentResolver().openOutputStream(uri)){out.write(bytes);}values.clear();values.put(android.provider.MediaStore.Downloads.IS_PENDING,0);getContentResolver().update(uri,values,null,null);}else{try(OutputStream out=new FileOutputStream(new File(getExternalFilesDir(android.os.Environment.DIRECTORY_DOWNLOADS),name))){out.write(bytes);}}runOnUiThread(()->android.widget.Toast.makeText(MainActivity.this,"Report saved",0).show());}catch(Exception e){runOnUiThread(()->android.widget.Toast.makeText(MainActivity.this,"Could not save report",0).show());}}
 @JavascriptInterface public String test(){if(!prefs.contains("printer"))return "{\"error\":\"Select a printer first\"}";runOnUiThread(()->startForegroundService(new Intent(MainActivity.this,QueueService.class).setAction("TEST")));return "{\"ok\":true}";}
 String error(Exception e){try{return new JSONObject().put("error",e.getMessage()).toString();}catch(Exception ignored){return "{}";}}
 }
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==11&&upload!=null){upload.onReceiveValue(WebChromeClient.FileChooserParams.parseResult(result,data));upload=null;}}
 @Override public void onBackPressed(){if(web.canGoBack())web.goBack();else super.onBackPressed();}
 @Override protected void onResume(){super.onResume();if(web!=null)CookieManager.getInstance().flush();}
}
